from typing import List


def find_minimum_time(processSize: List[int], capacity: List[int]) -> int:
    if not processSize:
        return 0
    procs = sorted(processSize, reverse=True)
    caps = sorted(capacity, reverse=True)
    if procs[0] > caps[0]:
        return -1
    n, m = len(procs), len(caps)

    def ok(k: int) -> bool:
        # 每台处理器最多 k 个任务：最大的 k 个给容量最大的处理器，依次类推
        for i, sz in enumerate(procs):
            j = i // k
            if j >= m or caps[j] < sz:
                return False
        return True

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    return 2 * lo - 1     # k 个任务：k 秒执行 + (k-1) 秒停顿


if __name__ == "__main__":
    print(find_minimum_time([2, 5, 3], [6, 2, 4]))
    print(find_minimum_time([1, 2, 3, 4, 6], [4, 1, 4]))
    print(find_minimum_time([1, 2, 3, 4], [4, 1, 4]))
    print(find_minimum_time([2, 5, 8], [6, 7, 4]))
